describe('Row Selection Badge Count', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should display badge count when multiple rows are selected', () => {
    // Verify table is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Select first row
    cy.get('[data-testid="row-1"]').click();

    // Verify badge appears with count 1
    cy.get('[data-testid="selected-row-badge"]').should('be.visible');
    cy.get('[data-testid="selected-row-badge"]').should('contain', '1');

    // Select second row
    cy.get('[data-testid="row-2"]').click();

    // Verify badge updates to count 2
    cy.get('[data-testid="selected-row-badge"]').should('contain', '2');

    // Select third row
    cy.get('[data-testid="row-3"]').click();

    // Verify badge updates to count 3
    cy.get('[data-testid="selected-row-badge"]').should('contain', '3');

    // Verify badge styling for multiple selections
    cy.get('[data-testid="selected-row-badge"]').should('have.class', 'badge-primary');
  });

  it('should handle badge count reset when selection is cleared', () => {
    // Select first row
    cy.get('[data-testid="row-1"]').click();
    cy.get('[data-testid="selected-row-badge"]').should('contain', '1');

    // Select second row
    cy.get('[data-testid="row-2"]').click();
    cy.get('[data-testid="selected-row-badge"]').should('contain', '2');

    // Clear selection
    cy.get('[data-testid="clear-selection-button"]').click();

    // Verify badge is no longer visible
    cy.get('[data-testid="selected-row-badge"]').should('not.exist');

    // Verify no rows are selected
    cy.get('[data-testid="row-1"]').should('not.have.class', 'selected');
    cy.get('[data-testid="row-2"]').should('not.have.class', 'selected');

    // Verify badge count is 0 (or not displayed)
    cy.get('[data-testid="selected-row-badge"]').should('not.exist');
  });
});
